insert into public.events (id, start_date, end_date, title, org, place, cat, pub, status, description, url, published) values
('sdi26', '2026-11-16', '2026-11-20', 'Semaine de l''industrie avec Elles bougent', 'Elles bougent', 'Partout en France', 'campagne', array['col','lyc','etu']::text[], 'ok', 'Visites de sites industriels, rencontres avec des marraines ingénieures et techniciennes, dans le cadre de la semaine nationale de l''industrie. Focus Défense le 19 novembre.', 'https://www.ellesbougent.com', true),
('ijc26', '2026-11-24', null, 'Remise du Prix Irène Joliot-Curie 2026', 'Ministère de l''Enseignement supérieur et de la Recherche · Académie des sciences', 'Paris, Coupole de l''Académie des sciences', 'prix', array['pro','all']::text[], 'ok', '25e édition du prix qui met en lumière des carrières de femmes scientifiques : Femme scientifique de l''année, Jeunes femmes scientifiques, Femme recherche & entreprise.', 'https://www.enseignementsup-recherche.gouv.fr/fr/PIJC-2026-candidature', true),
('mm26', '2026-11-28', '2026-11-29', 'Les Mini-Marmottes : un week-end de maths', 'Université de Genève · Filles & Maths', 'Genève (Suisse)', 'rencontre', array['col']::text[], 'ok', 'Ateliers de recherche et rencontres avec des mathématiciennes pour des collégiennes du canton de Genève.', 'https://www.unige.ch/math/GEM/nos-activites/filles-maths/mini-marmottes', true),
('ebo26', '2026-11-30', '2026-12-04', 'Elles bougent pour l''orientation', 'Elles bougent', 'Collèges, partout en France', 'campagne', array['col']::text[], 'ok', 'Des marraines ingénieures, techniciennes ou expertes de la tech viennent présenter leur métier directement en classe.', 'https://www.ellesbougent.com', true),
('jfmi', '2026-09-01', '2027-06-30', 'Journées « Filles, maths et informatique : une équation lumineuse »', 'femmes & mathématiques · Animath', 'Dans de nombreuses villes en France', 'rencontre', array['col','lyc']::text[], 'year', 'Une journée pour collégiennes et lycéennes : conférence d''une chercheuse, speed-meetings avec des femmes scientifiques, théâtre-forum et ateliers sur les stéréotypes.', 'https://femmes-et-maths.fr/de-lecole-au-lycee/filles-et-maths-une-equation-lumineuse/', true),
('rjmi', '2026-09-01', '2027-06-30', 'Rendez-vous des Jeunes Mathématiciennes et Informaticiennes (RJMI)', 'Animath · femmes & mathématiques', 'Universités et centres Inria', 'rencontre', array['lyc']::text[], 'year', 'Deux à trois jours pour une trentaine de lycéennes de 1re et terminale : problèmes ouverts, algorithmique et échanges avec des chercheuses.', 'https://filles-et-maths.fr/rjmi/', true),
('ing27c', '2027-01-08', '2027-03-08', 'Ingénieuses 2027 : appel à projets et candidatures', 'CDEFI', 'En ligne', 'prix', array['etu','pro']::text[], 'est', 'Concours qui récompense les écoles d''ingénieurs, élèves-ingénieures et femmes ingénieures engagées pour la mixité. En 2026, l''appel courait du 8 janvier au 8 mars.', 'https://www.ingenieuses.fr', true),
('frcf27', '2027-02-02', '2027-02-04', 'Forum Réseaux & Carrières au Féminin', 'Elles bougent', 'En ligne', 'emploi', array['etu']::text[], 'est', 'Forum de recrutement 100 % féminin : plus de 100 entreprises de l''industrie et du numérique, entretiens et ateliers RH. L''édition 2026 a eu lieu du 3 au 5 février.', 'https://www.ellesbougent.com', true),
('ifws27', '2027-02-11', null, 'Journée internationale des femmes et des filles de science', 'Nations unies', 'Partout dans le monde', 'jour', array['all']::text[], 'ok', 'Chaque 11 février, journée de l''ONU pour l''accès et la participation pleine et égale des femmes et des filles aux sciences.', 'https://www.un.org/fr/observances/women-and-girls-in-science-day', true),
('fwis27c', '2027-02-11', '2027-03-23', 'Prix Jeunes Talents France L''Oréal-UNESCO : appel à candidatures', 'Fondation L''Oréal · Académie des sciences · Commission nationale française pour l''UNESCO', 'En ligne', 'prix', array['pro']::text[], 'est', '35 dotations pour des doctorantes et post-doctorantes (15 000 € et 20 000 €). En 2026, l''appel était ouvert du 11 février au 23 mars.', 'https://www.forwomeninscience.com', true),
('8m27', '2027-03-08', null, 'Journée internationale des droits des femmes', 'Nations unies', 'Partout dans le monde', 'jour', array['all']::text[], 'ok', 'De nombreux laboratoires, écoles et universités organisent des événements sur l''égalité en sciences autour du 8 mars.', 'https://www.un.org/fr/observances/womens-day', true),
('smf27', '2027-03-11', null, 'Sciences, un métier de femmes ! (#11)', 'Femmes & Sciences · ENS de Lyon', 'Lyon, Saint-Étienne et d''autres villes', 'rencontre', array['lyc']::text[], 'est', 'Près de 500 lycéennes rencontrent des chercheuses, ingénieures et techniciennes. Organisée chaque année autour du 8 mars ; en 2026, le 12 mars.', 'https://www.ens-lyon.fr/savoirs/culture-sciences-et-societe/grands-evenements/sciences-un-metier-de-femmes', true),
('gict27', '2027-04-22', null, 'Girls in ICT Day', 'Union internationale des télécommunications (UIT)', 'Partout dans le monde', 'jour', array['col','lyc','etu']::text[], 'ok', 'Le 4e jeudi d''avril, journée internationale pour encourager les filles vers le numérique et les technologies de l''information.', 'https://www.itu.int/women-and-girls/girls-in-ict/', true),
('ing27', '2027-05-18', null, 'Cérémonie de remise des prix Ingénieuses', 'CDEFI', 'Paris', 'prix', array['etu','pro']::text[], 'est', 'Remise des prix aux écoles, élèves-ingénieures et femmes ingénieures lauréates. En 2026, la cérémonie s''est tenue le 19 mai.', 'https://www.ingenieuses.fr', true),
('ijc27c', '2027-05-11', '2027-06-30', 'Prix Irène Joliot-Curie 2027 : appel à candidatures', 'Ministère de l''Enseignement supérieur et de la Recherche', 'En ligne', 'prix', array['pro']::text[], 'est', 'Candidatures pour les catégories du prix. En 2026, l''appel a été lancé le 11 mai et clos le 30 juin.', 'https://www.enseignementsup-recherche.gouv.fr', true),
('fwisi27', '2027-06-14', '2027-06-18', 'Prix internationaux L''Oréal-UNESCO & Semaine Pour les Femmes et la Science', 'Fondation L''Oréal · UNESCO', 'Paris', 'prix', array['pro','all']::text[], 'est', 'Cérémonie des prix internationaux (édition 2027 : sciences physiques, mathématiques, informatique…). Annoncée pour juin 2027, date à confirmer.', 'https://www.forwomeninscience.com', true),
('fds27', '2027-10-01', '2027-10-11', 'Fête de la science', 'Ministère de l''Enseignement supérieur et de la Recherche', 'Partout en France', 'campagne', array['all']::text[], 'est', 'Dix jours d''événements gratuits dans les labos : beaucoup proposent des rencontres avec des chercheuses. En 2026, du 2 au 12 octobre.', 'https://www.fetedelascience.fr', true),
('ald27', '2027-10-12', null, 'Ada Lovelace Day', 'Finding Ada', 'Partout dans le monde', 'jour', array['all']::text[], 'ok', 'Le 2e mardi d''octobre, journée qui célèbre les réussites des femmes en sciences, technologie, ingénierie et mathématiques.', 'https://findingada.com', true),
('fwis27', '2027-10-05', null, 'Cérémonie des Prix Jeunes Talents France L''Oréal-UNESCO', 'Fondation L''Oréal · Académie des sciences', 'Paris', 'prix', array['pro']::text[], 'est', 'Remise des 35 prix aux jeunes chercheuses lauréates. En 2026, la cérémonie a eu lieu le 6 octobre.', 'https://www.forwomeninscience.com', true),
('rjmi26c', '2026-01-23', '2026-01-24', 'RJMI à l''Université de Caen Normandie', 'Animath · femmes & mathématiques · LMNO', 'Caen', 'rencontre', array['lyc']::text[], 'ok', '4e édition normande des Rendez-vous des jeunes mathématiciennes et informaticiennes.', 'https://filles-et-maths.fr/rjmi/', true),
('frcf26', '2026-02-03', '2026-02-05', 'Forum Réseaux & Carrières au Féminin (14e édition)', 'Elles bougent', 'En ligne', 'emploi', array['etu']::text[], 'ok', '115 entreprises des secteurs industriels et numériques réunies en ligne.', 'https://www.ellesbougent.com', true),
('ifws26', '2026-02-11', null, 'Journée internationale des femmes et des filles de science', 'Nations unies', 'Partout dans le monde', 'jour', array['all']::text[], 'ok', 'Édition 2026 de la journée de l''ONU.', 'https://www.un.org/fr/observances/women-and-girls-in-science-day', true),
('smf26', '2026-03-12', '2026-03-13', 'Sciences, un métier de femmes ! — les 10 ans', 'Femmes & Sciences · ENS de Lyon', 'Lyon (12 mars), Saint-Étienne (13 mars)', 'rencontre', array['lyc']::text[], 'ok', '10e édition de la journée pour les lycéennes de la région.', 'https://www.ens-lyon.fr/savoirs/culture-sciences-et-societe/grands-evenements/sciences-un-metier-de-femmes', true),
('jfmi26s', '2026-04-10', null, 'Journée Filles, Maths et Informatique à Sorbonne Université', 'Sorbonne Université · femmes & mathématiques · Animath', 'Paris, faculté des Sciences et ingénierie', 'rencontre', array['col','lyc']::text[], 'ok', 'Découverte des métiers des maths et de l''informatique avec des étudiantes et des femmes scientifiques.', 'https://www.sorbonne-universite.fr/evenements/journees-filles-maths-et-informatique', true),
('ing26', '2026-05-19', null, 'Cérémonie Ingénieuses 2026', 'CDEFI', 'Paris', 'prix', array['etu','pro']::text[], 'ok', '16e cérémonie : 62 projets d''écoles, 84 candidatures d''élèves-ingénieures et 72 de femmes ingénieures.', 'https://www.ingenieuses.fr', true),
('fds26', '2026-10-02', '2026-10-12', 'Fête de la science 2026 — « Saveurs savantes »', 'Ministère de l''Enseignement supérieur et de la Recherche', 'Partout en France', 'campagne', array['all']::text[], 'ok', '35e édition.', 'https://www.fetedelascience.fr', true),
('fwis26', '2026-10-06', null, 'Cérémonie des Prix Jeunes Talents France L''Oréal-UNESCO 2026', 'Fondation L''Oréal · Académie des sciences', 'Paris', 'prix', array['pro']::text[], 'ok', '20e édition : 35 jeunes chercheuses récompensées parmi plus de 800 candidates.', 'https://www.forwomeninscience.com', true)
insert into public.actors (id, name, match_key, initials, url, pub, description, sort) values
('eb-0', 'Elles bougent', 'Elles bougent', 'EB', 'https://www.ellesbougent.com', array['col','lyc','etu']::text[], 'Association qui fait découvrir aux collégiennes, lycéennes et étudiantes les métiers d''ingénieure et de technicienne, grâce à un réseau de marraines dans les entreprises partenaires.', 10),
('fm-1', 'femmes & mathématiques', 'femmes & mathématiques', 'f&m', 'https://femmes-et-maths.fr', array['col','lyc','etu','pro']::text[], 'Association qui agit pour la place des femmes en mathématiques : Journées « Filles, maths et informatique », marrainage d''élèves, ressources sur les stéréotypes.', 20),
('an-2', 'Animath', 'Animath', 'An', 'https://www.animath.fr', array['col','lyc']::text[], 'Association qui développe le goût des maths chez les jeunes ; co-organise les RJMI et les Journées Filles, maths et informatique.', 30),
('fs-3', 'Femmes & Sciences', 'Femmes & Sciences', 'F&S', 'https://www.femmesetsciences.fr', array['lyc','etu','pro']::text[], 'Association de femmes scientifiques qui organise « Sciences, un métier de femmes ! » et propose du mentorat aux étudiantes.', 40),
('cd-4', 'CDEFI — Ingénieuses', 'CDEFI', 'CD', 'https://www.ingenieuses.fr', array['etu','pro']::text[], 'La Conférence des directeurs des écoles françaises d''ingénieurs porte depuis 2011 l''opération Ingénieuses : campagne nationale et concours pour la mixité en école d''ingénieurs.', 50),
('fl-5', 'Fondation L''Oréal — Pour les Femmes et la Science', 'Fondation L''Oréal', 'FL', 'https://www.forwomeninscience.com', array['pro']::text[], 'Avec l''UNESCO et l''Académie des sciences, soutient les chercheuses : prix internationaux et 35 dotations Jeunes Talents par an en France.', 60),
('me-6', 'Ministère de l''Enseignement supérieur et de la Recherche', 'Ministère de l''Enseignement supérieur', 'ME', 'https://www.enseignementsup-recherche.gouv.fr', array['all','pro']::text[], 'Organise le Prix Irène Joliot-Curie, qui valorise des carrières de femmes scientifiques, et la Fête de la science.', 70),
('un-7', 'Nations unies & UIT', 'Nations unies', 'UN', 'https://www.un.org/fr/observances/women-and-girls-in-science-day', array['all']::text[], 'Instaurent les journées mondiales : femmes et filles de science (11 février), droits des femmes (8 mars), Girls in ICT Day (avril).', 80)
insert into public.formations (id, name, type, acces, statut, lieu, domaines, description, mixite, url, sort) values
('epf', 'EPF École d''ingénieurs', 'ing', array['postbac']::text[], 'Privée d''intérêt général', 'Paris-Cachan, Troyes, Montpellier, Saint-Nazaire', array['inge','info','env']::text[], 'École d''ingénieurs généraliste, fondée en 1925 sous le nom d''École polytechnique féminine.', '<b>ParityLab</b> : voie d''admission réservée aux candidates via Parcoursup, avec 100 places à la rentrée 2026. Également : stage de seconde « Dans la peau d''une ingénieure ».', 'https://www.epf.fr', 10),
('insa', 'Groupe INSA', 'ing', array['postbac']::text[], 'Publique', 'Lyon, Toulouse, Rennes, Rouen, Strasbourg, Centre-Val de Loire, Hauts-de-France', array['inge','info','chim','bio','env']::text[], 'Réseau d''écoles d''ingénieurs publiques en cinq ans après le bac, avec un large choix de spécialités.', null, 'https://www.groupe-insa.fr', 20),
('polytech', 'Réseau Polytech', 'ing', array['postbac','postprepa']::text[], 'Publique (écoles universitaires)', 'Une quinzaine de villes en France', array['inge','info','bio','env','chim']::text[], 'Écoles d''ingénieurs des universités, accessibles après le bac (parcours PeiP) ou après un bac+2.', '<b>Polytech Marseille</b> : « Les ingénieuses du piano solaire », projet mené avec un collège marseillais.', 'https://www.polytech-reseau.org', 30),
('cs', 'CentraleSupélec', 'ing', array['postprepa']::text[], 'Publique', 'Paris-Saclay, Metz, Rennes', array['inge','info','maths','phys']::text[], 'Grande école d''ingénieurs généraliste, principalement recrutée après une classe préparatoire.', '<b>Summer Camp</b> : école d''été pour des élèves de seconde sur le campus de Paris-Saclay, récompensée par le prix Ingénieuses 2022.', 'https://www.centralesupelec.fr', 40),
('ecn', 'Centrale Nantes', 'ing', array['postprepa']::text[], 'Publique', 'Nantes', array['inge','info','env']::text[], 'École d''ingénieurs généraliste du Groupe des Écoles Centrale.', 'Projet <b>« Ingénierie : pour un avenir au féminin »</b>, nommé au concours Ingénieuses 2026.', 'https://www.ec-nantes.fr', 50),
('ecl', 'Centrale Lyon', 'ing', array['postprepa']::text[], 'Publique', 'Écully (Lyon)', array['inge','info','phys']::text[], 'École d''ingénieurs généraliste du Groupe des Écoles Centrale.', 'Projet <b>« Des femmes et des sciences »</b>, mené avec un collège d''Écully dans le cadre du label Cap Ingénieuses.', 'https://www.ec-lyon.fr', 60),
('cytech', 'CY Tech', 'ing', array['postbac','postprepa']::text[], 'Publique (CY Cergy Paris Université)', 'Cergy, Pau', array['info','maths','inge']::text[], 'École d''ingénieurs de CY Cergy Paris Université, avec une prépa intégrée après le bac.', 'Projet <b>« Ambitieuses Ingénieuses »</b>, nommé au concours Ingénieuses 2026.', 'https://cytech.cyu.fr', 70),
('epita', 'EPITA', 'ing', array['postbac']::text[], 'Privée', 'Paris et campus en régions', array['info']::text[], 'École d''ingénieurs spécialisée en informatique et numérique.', 'Projet <b>« 404Elles »</b> de l''association étudiante Epitrophi, récompensé par le prix Ingénieuses 2022.', 'https://www.epita.fr', 80),
('esilv', 'ESILV', 'ing', array['postbac']::text[], 'Privée', 'Paris-La Défense, Nantes, Montpellier', array['info','inge','maths']::text[], 'École d''ingénieurs du numérique, de la data et de l''industrie.', 'Partenariat <b>STEM4ALL</b> pour les parcours féminins en IA et cybersécurité ; école partenaire d''Elles bougent.', 'https://www.esilv.fr', 90),
('junia', 'Junia', 'ing', array['postbac']::text[], 'Privée', 'Lille', array['inge','info','env','bio']::text[], 'Grande école d''ingénieurs aux spécialités très variées (numérique, énergie, agriculture, bâtiment…).', 'Projet <b>« Mission Chronos »</b>, lauréat du prix lycéen Ingénieuses 2024.', 'https://www.junia.com', 100),
('enit', 'ENI Tarbes', 'ing', array['postbac']::text[], 'Publique', 'Tarbes', array['inge','env']::text[], 'École nationale d''ingénieurs, spécialisée en génie mécanique, industriel et matériaux.', 'Projet étudiant récompensé par le <b>prix du projet le plus original</b> au concours Ingénieuses 2025.', 'https://www.enit.fr', 110),
('espci', 'ESPCI Paris - PSL', 'ing', array['postprepa']::text[], 'Publique', 'Paris 5e', array['phys','chim','bio']::text[], 'École d''ingénieurs-chercheurs en physique, chimie et biologie.', '<b>Semaine de découverte gratuite</b> des sciences expérimentales pour une vingtaine de lycéennes, pendant les vacances d''octobre.', 'https://www.espci.psl.eu', 120),
('icam', 'Icam', 'ing', array['postbac']::text[], 'Privée', 'Plusieurs campus en France', array['inge','env']::text[], 'École d''ingénieurs généraliste, avec des parcours en formation initiale et en apprentissage.', '<b>30 à 40 % de filles</b> en première année à la rentrée 2025, selon les campus et les parcours.', 'https://www.icam.fr', 130),
('am', 'Arts et Métiers', 'ing', array['postbac','postprepa']::text[], 'Publique', 'Huit campus en France', array['inge','env']::text[], 'Grande école d''ingénieurs en mécanique, énergie et industrie ; propose aussi un bachelor après le bac.', 'Ouvre ses campus aux <b>collégiennes et lycéennes avec Elles bougent</b> pour faire découvrir ses formations et métiers.', 'https://artsetmetiers.fr', 140),
('eseo', 'ESEO', 'ing', array['postbac']::text[], 'Privée', 'Angers, Paris, Dijon', array['info','inge']::text[], 'École d''ingénieurs généraliste en électronique, informatique et numérique.', '<b>Lauréate du concours Ingénieuses 2022</b> pour ses actions en faveur de la mixité.', 'https://eseo.fr', 150),
('ginp', 'Grenoble INP - UGA', 'ing', array['postbac','postprepa']::text[], 'Publique', 'Grenoble, Valence', array['inge','info','phys','chim','env']::text[], 'Groupe d''écoles d''ingénieurs (énergie, numérique, matériaux, génie industriel…), avec une prépa intégrée.', null, 'https://www.grenoble-inp.fr', 160),
('utc', 'Université de technologie de Compiègne (UTC)', 'ing', array['postbac','postprepa']::text[], 'Publique', 'Compiègne', array['inge','info','bio','env']::text[], 'École d''ingénieurs en cinq ans après le bac, à la carte (génie biologique, informatique, mécanique…).', null, 'https://www.utc.fr', 170),
('imta', 'IMT Atlantique', 'ing', array['postprepa']::text[], 'Publique', 'Brest, Nantes, Rennes', array['info','env','inge']::text[], 'Grande école d''ingénieurs du numérique, de l''énergie et de l''environnement.', null, 'https://www.imt-atlantique.fr', 180),
('cpge', 'Classes préparatoires scientifiques (MPSI, MP2I, PCSI, PTSI, BCPST…)', 'prepa', array['postbac']::text[], 'Publique et privée', 'Lycées partout en France', array['maths','phys','chim','info','bio']::text[], 'Deux années intensives après le bac pour préparer les concours des grandes écoles d''ingénieurs, vétérinaires ou normales supérieures.', null, 'https://www.onisep.fr', 190),
('but', 'BUT scientifiques (Informatique, GEII, Mesures physiques, Chimie, Génie biologique…)', 'but', array['postbac']::text[], 'Publique', 'IUT partout en France', array['info','inge','phys','chim','bio']::text[], 'Bachelor universitaire de technologie en trois ans : formation concrète, stages, alternance possible, et poursuite d''études en école d''ingénieurs.', null, 'https://www.onisep.fr', 200),
('lic', 'Licences scientifiques (maths, informatique, physique, chimie, sciences de la vie…)', 'licence', array['postbac']::text[], 'Publique', 'Universités partout en France', array['maths','info','phys','chim','bio','env']::text[], 'Trois ans à l''université pour approfondir une discipline, puis master, doctorat ou école d''ingénieurs. Les doubles licences existent aussi.', null, 'https://www.onisep.fr', 210),
('bts', 'BTS scientifiques et techniques (CIEL, SIO, Bioanalyses et contrôles…)', 'bts', array['postbac']::text[], 'Publique et privée', 'Lycées partout en France', array['info','inge','bio']::text[], 'Deux ans pour un métier technique (réseaux, cybersécurité, électronique, laboratoire…), avec des poursuites d''études possibles.', null, 'https://www.onisep.fr', 220)
