-- =====================================================================
--  NOVA — Contenu de départ (à exécuter APRÈS schema.sql)
--  Réexécutable : les lignes existantes sont mises à jour.
--  Sources : sites officiels des organisateurs, consultés en novembre 2026.
-- =====================================================================

-- Événements
on conflict (id) do update set start_date=excluded.start_date, end_date=excluded.end_date, title=excluded.title,
  org=excluded.org, place=excluded.place, cat=excluded.cat, pub=excluded.pub, status=excluded.status,
  description=excluded.description, url=excluded.url, published=excluded.published;

-- Acteurs
on conflict (id) do update set name=excluded.name, match_key=excluded.match_key, initials=excluded.initials,
  url=excluded.url, pub=excluded.pub, description=excluded.description, sort=excluded.sort;

-- Formations
on conflict (id) do update set name=excluded.name, type=excluded.type, acces=excluded.acces, statut=excluded.statut,
  lieu=excluded.lieu, domaines=excluded.domaines, description=excluded.description, mixite=excluded.mixite,
  url=excluded.url, sort=excluded.sort;
